INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1yygy6pelm', 'course-bili-bv1yygy6pelm', '100001', '0', 'BILI-LANG-EKAC6E', 'course-category-language', 'instructor-bili-3546715428752222', '全新雅思词汇带背！21天学完6600雅思单词！（全新配套例句+刷词工具）| 雅思词汇带背讲解', '26 讲完整课程 · 19 小时 1 分钟', '我做了一套80万播放的词汇讲解，但因为种种原因下架了。" 现在它回来了，而且不是简单的重新上传——我花了2个月时间，从头到尾重新设计了一遍。一、和原书有什么不同？', '课程简介：一年前，我做了一套80万播放的词汇讲解，但因为种种原因下架了。" 现在它回来了，而且不是简单的重新上传——我花了2个月时间，从头到尾重新设计了一遍。一、和原书有什么不同？学习顺序完全重构：原书从"自然地理"开始讲，我从"时间与存在"开始讲。因为你从小到大认识世界的顺序，是先感知时间，再认识自我，最后才理解山川河流。我按照这个认知弧线重新编排了22个章节，让词汇记忆自然生长，而不是死记硬背。内容深度升级：每个单词的例句、词根拆解、拓展知识，全部是重新编写的，和原书没有任何重复；每章在原书基础上额外补充了高频相关词汇，标注了"核心/高频/低频/识记"标签，让你知道哪些必须会拼写，哪些只要认识就行。交互式课件 + 刷词神器：录课用的每一张词汇卡片，都是我自己做的动态课件；我还专门为这套课程开发了一个「真经刷词神器」（开源工具），支持22个章节切换、看中文拼写/听音拼写/随机两种模式、错题本、生词本、倒计时练习、每日目标打卡，所有数据自动保存。课件和刷词工具的源代码我全部开源，下载方式见评论区置顶。二、课程适合谁？正在备考雅思/托福，需要系统刷词汇的同学。手上有那本经典词汇书，想找一个深度讲解配套课程的人。喜欢"理解后再记忆"，而不是死背单词表的同学。三、如何使用这套课程？每节课我会告诉你对标原书的哪一章，你既可以跟 课程结构：共 4 章 26 讲，累计时长 19 小时 1 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/1b06e8456a75b39bd5ef395aae140728ca486f17.jpg', '["语言学习","口语训练","考试备考","完结","雅思词汇","全新配套例句"]', 68473, 26, 195729, '4.5', 52352, 'BV1yyGy6PELM', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'lexi学姐教雅思', 0, 'tenant', 'published', '2026-05-27T07:57:31.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
