INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-1980796', 'course-bili-season-1980796', '100001', '0', 'BILI-LANG-HG7SX6', 'course-category-language', 'instructor-bili-45465285', '新版标准日本语初级同步练习第二单元末练习。日语自学/学日语/日语语法/日语单词/日语课文/日语N5/日语入门/零基础学日语/初级日语', '30 讲完整课程 · 13 小时 18 分钟', '本课重点语法 １．星期和时间 2.今~時~分です表示"现在~点~分" ，30分可以用"半"代替。3.动词四种时态 4.~（时间）に＋动词，表示动作发生的具体时间。助词"に"接在时间后表示动作发生的具体时间。', '课程简介：本课重点语法 １．星期和时间 2.今~時~分です表示"现在~点~分" ，30分可以用"半"代替。3.动词四种时态 4.~（时间）に＋动词，表示动作发生的具体时间。助词"に"接在时间后表示动作发生的具体时间。5.~（时间）から（时间）まで＋动词 "从~开始到~结束" 表示动作发生的某个期间（时间段）。6．~いつ＋动词ますか／~いつですか "什么时候" 7．は表示对比 8．日期 9.（场所）へ＋移动动词表示移动行为的目的地。"へ"表示移动行为的目的地。例：明日図書館へ行きます。明天去图书馆。10.（场所）から＋移动动词表示移动的起点。"から"表示移动范围的起点。例：スミスさんは来週アメリカから来ます。史密斯先生下周从美国来。11.（人）と＋动词表示和"某人"一起做某事。例："と"表示共同做某事的对象。例：友達と学校へ帰ります。和朋友一起回学校。12.（交通工具）で＋动词表示使用某交通工具做某事。"で"表示使用某种交通工具。例：自転車で公園へ行きます。骑自行车去公园。13．（場所）から（場所）まで＋动词表示从某地到某地。"から"表示范围的起点。"まで"表示范围的终点。例：上海から北京までフェリーで行きます。从上海坐轮船去北京。14．に／で／へ／から／まで／と＋は 构成复合形式，表示对比强调。15．（名词）をください"请给我~（东西）"买东西、点餐或者请求~物品时用。例： 课程结构：共 1 章 30 讲，累计时长 13 小时 18 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/a4329010acc624c34a1e1da34508d3702c03c137.jpg', '["语言学习","口语训练","考试备考","学日语","日语语法","日语单词"]', 47925, 30, 286, '4.5', 42, 'BV1ag4y1o7XM', NULL, NULL, NULL, 1, 0, 'standard', NULL, '笨比熊聊日语', 0, 'tenant', 'published', '2023-12-09T10:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
