    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1je411s7tf', 'course-bili-bv1je411s7tf', '100001', '0', 'BILI-LANG-R8UPUU', 'course-category-language', 'instructor-bili-7403605', '法语快速入门', '44 讲完整课程 · 8 小时 44 分钟', '法语是世界上最浪漫的语言之一，也因此吸引了不少法语爱好者前来学习，而法语快速入门则是为法语爱好者提供的零基础法语语言与文化课程。本课程针对法语A1的学生开设，开篇四讲采用法语教学，帮你先感知法语的语调。第五课配套语音的', '课程简介：法语是世界上最浪漫的语言之一，也因此吸引了不少法语爱好者前来学习，而法语快速入门则是为法语爱好者提供的零基础法语语言与文化课程。本课程针对法语A1的学生开设，开篇四讲采用法语教学，帮你先感知法语的语调。第五课配套语音的讲解，之后侧重对课文的梳理，帮你打开法语学习的大门！课程结构：共 6 章 44 讲，累计时长 8 小时 44 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/e948c823bafc520f4f2139f2782e52b8c7f4a92e.jpg', '["语言学习","口语训练","考试备考","法语快速入门"]', 31476, 44, 3753, '4.4', 1102, 'BV1je411s7TF', NULL, NULL, NULL, 1, 0, 'standard', NULL, '童哲校长', 0, 'tenant', 'published', '2020-04-21T09:07:47.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
