    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1nu4y147ku', 'course-bili-bv1nu4y147ku', '100001', '0', 'BILI-LANG-EBKBRX', 'course-category-language', 'instructor-bili-1152114171', '细嚼慢咽啃英语——E英语教程第一册（全网独家打字机字幕效果__耳目一新的听读学习&听力练习&听写训练-语音文字逐词对照-英语听力-英文阅读精听精读泛读朗读背诵）', '1 讲完整课程 · 59 分钟', '细嚼慢咽啃英语的三大核心分别是"听读学习"、"听力练习"和"听写训练"。听读学习(细嚼)："聆听优先，先入为主"，听后即刻对照阅读，然后迅速翻译，并参阅译文对比。听力练习(慢咽)：增加了难度。', '课程简介：细嚼慢咽啃英语的三大核心分别是"听读学习"、"听力练习"和"听写训练"。听读学习(细嚼)："聆听优先，先入为主"，听后即刻对照阅读，然后迅速翻译，并参阅译文对比。听力练习(慢咽)：增加了难度。循环播放语音时，必须手动拼写（简拼）出每个单词的首字母（遇到困难可借助提示键自动完成）。听写训练(啃)：难度最大，同时效果最佳。循环播放语音时，必须完整拼写（全拼）出每个单词，可选择"顺序听写"或"听出哪词写哪词"，在听写训练过程中熟练掌握词汇。课程结构：共 1 章 1 讲，累计时长 59 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/d27b410c2c0f990d9ecdf0693c6b4f69294d2dda.jpg', '["语言学习","口语训练","考试备考","E英语教程第一册","全网独家打字机字幕效果"]', 3582, 1, 2534, '4.8', 336, 'BV1NU4y147ku', NULL, NULL, NULL, 1, 0, 'standard', NULL, '细嚼慢咽啃英语', 0, 'tenant', 'published', '2021-01-18T03:02:09.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
