INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1qm411i7sm', 'course-bili-bv1qm411i7sm', '100001', '0', 'BILI-LANG-WHGGY7', 'course-category-language', 'instructor-bili-447772450', '一听就会的语法入门课！超详细！新编日语教程第一册，从零开始带你掌握日语现代语法！', '29 讲完整课程 · 21 小时 14 分钟', '小伙伴们大家好，我是一位教日语6年的日语老师。这两年一直线上给同学们上考研日语203的课，受到了很多同学们的鼓励和支持，所以决定把适合日语零基础的《新编日语教程》第一册的课程全部放上来给大家一起学习。', '课程简介：小伙伴们大家好，我是一位教日语6年的日语老师。这两年一直线上给同学们上考研日语203的课，受到了很多同学们的鼓励和支持，所以决定把适合日语零基础的《新编日语教程》第一册的课程全部放上来给大家一起学习。大家有什么疑惑可以评论区一起讨论，日语小白到大神的第一课语法学习💪你值得拥有！课程结构：共 4 章 29 讲，累计时长 21 小时 14 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/053ea8a885cc0d0becec7f5ae17feb3ec462e425.png', '["语言学习","口语训练","考试备考","考研日语203零基础"]', 76496, 29, 17171, '4.4', 3011, 'BV1qM411i7sM', NULL, NULL, NULL, 1, 0, 'standard', NULL, '修桑的考研日语教室', 0, 'tenant', 'published', '2023-02-02T07:28:14.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
