    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1erp96yeq6', 'course-bili-bv1erp96yeq6', '100001', '0', 'BILI-LANG-X6XZ15', 'course-category-language', 'instructor-bili-108610948', '德语发音入门课：从字母、元音到辅音（全18讲）', '18 讲完整课程 · 2 小时 36 分钟', '德语学习请找：DeutschLena（说明来意） 从德语字母表和拼读基础开始，逐步学习元音长短音、双元音、变元音及常见辅音。结合课堂示范、学生跟读、听辨与纠错练习，按顺序建立发音基础。本合集整理自两节原课，保留其已有内容', '课程简介：德语学习请找：DeutschLena（说明来意） 从德语字母表和拼读基础开始，逐步学习元音长短音、双元音、变元音及常见辅音。结合课堂示范、学生跟读、听辨与纠错练习，按顺序建立发音基础。本合集整理自两节原课，保留其已有内容，不将其表述为覆盖全部德语发音规则的完整课程。课程结构：共 3 章 18 讲，累计时长 2 小时 36 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/8365ca4710fd4d5aad849f52d20ed2f0ac6ddb23.jpg', '["语言学习","口语训练","考试备考","德语发音入门课","从字母","元音到辅音"]', 9406, 18, 180, '4.5', 59, 'BV1ERp96yEq6', NULL, NULL, NULL, 1, 0, 'standard', NULL, '德语老师莉娜Lena', 0, 'tenant', 'published', '2026-10-12T08:05:45.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
